int queue[queue_size];
int visited[node_size];
int first_app[node_size];
int next[edge_size];

void bfs4() {
    int i, p;
    int qhead = 0, qtail = 0, iter=0;
    int s = 255;
    int niter=0, nupdate=0;

    queue[qtail] = s;
    qtail = qtail + 1;
    // Initialization
    for(int i = 0; i < node_size; i++){
        //II=4
        // #ifdef CGRA_COMPILER
        // please_map_me();
        // #endif 
        visited[i] = 0;
        first_app[i] = -1;
    }
    for(int i = edge_size -1; i>=0; i--){

      // #ifdef CGRA_COMPILER
      // please_map_me();
      // #endif 
        next[i]=first_app[src[i]];
        first_app[src[i]] = i;
    }

    visited[s] = 1;

    while(qhead!=qtail)
    {
        s = queue[qhead];
        qhead = qhead + 1;
        p = first_app[s];
        while(p!=-1){
            // niter++;
            // II = 14
            #ifdef CGRA_COMPILER
            please_map_me();
            #endif 

            // 1
            if(!visited[dest[p]]){
                nupdate+=1;
                visited[dest[p]]=1;
                queue[qtail] = dest[p];
                qtail = qtail + 1;
            }
            p=next[p];
            if (p==-1) break;

            // 2
            if (!visited[dest[p]]) {
                nupdate+=1;
                visited[dest[p]]=1;
                queue[qtail] = dest[p];
                qtail = qtail + 1;
            }
            p=next[p];
            if (p==-1) break;  

            // 3
            if (!visited[dest[p]]) {
                nupdate+=1;
                visited[dest[p]]=1;
                queue[qtail] = dest[p];
                qtail = qtail + 1;
            }
            p=next[p];
            if (p==-1) break;

            // 4
            if (!visited[dest[p]]) {
                nupdate+=1;
                visited[dest[p]]=1;
                queue[qtail] = dest[p];
                qtail = qtail + 1;
            }
            p=next[p];
            if (p==-1) break;
        }

    }
    printf("ITERATIONS: %d UPDATE: %d\n", niter, nupdate);
}

